<section class="page-header"><div><span class="eyebrow">Account security</span><h1>Change password</h1><p>Choose a strong password you do not use elsewhere.</p></div></section><div class="panel narrow-panel"><form class="entity-form" method="post" action="<?= url('account/password') ?>"><?= csrf_field() ?><div class="form-grid"><label class="wide">Current password<input type="password" name="current_password" required autocomplete="current-password"></label><label>New password<input type="password" name="new_password" required minlength="10" autocomplete="new-password"></label><label>Confirm new password<input type="password" name="new_password_confirmation" required minlength="10" autocomplete="new-password"></label></div><div class="form-actions"><a class="button button-secondary" href="<?= url('dashboard') ?>">Cancel</a><button class="button button-primary">Update password</button></div></form></div>
